actions.script:
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
def _org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def ef = ec.entity.find("zenith.erp.inventory.ProductStockView").condition("productTypeEnumId","PtAsset").orderBy("productName").limit(1000)
if (_org && _org != '_NA_') ef.condition("ownerPartyId", _org)
def raw = ef.list()
def intn = { v -> ec.l10n.format((v ?: 0) as BigDecimal, '#,##0') }
def num = { v -> ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00') }
rows = raw.collect { s ->
    def q=(s.totalQoh ?: 0) as BigDecimal; def r=(s.reorderPoint ?: 0) as BigDecimal
    def st = q <= 0 ? 'Out of Stock' : ((r > 0 && q <= r) ? 'Low Stock' : 'In Stock')
    [sku:(s.pseudoId ?: ''), product:(s.productName ?: ''), qoh:intn(s.totalQoh), atp:intn(s.totalAtp),
     rp:intn(s.reorderPoint), mrp:num(s.mrpAmount), status:st] }
rowCountStr = raw.size().toString()
